    mine0 = newey_west(y, X, 0)
    mine_ols = np.sqrt(np.diag(np.linalg.inv(X.T @ X)) * (mine0["resid"] @ mine0["resid"]) / (len(y) - 2))
    print(f"lags=0 is White's HC0 (SE {mine0['se'][0]:.6f} for alpha); plain OLS SE {mine_ols[0]:.6f};"
          f" HAC({lags}) SE {newey_west(y, X, lags)['se'][0]:.6f}")

    # ---------------------------------------------------------------- 4. Fama-MacBeth
    print("\n4. FAMA-MACBETH: monthly cross-sections of r_it on log(B/M) and log(cap), average slope")
    chars = {"log_bm": np.log(bm), "log_cap": np.log(mcap)}
    fm_ok = fama_macbeth(ret, chars, lag=1)
    fm_leak = fama_macbeth(ret, chars, lag=0, allow_lookahead=True)
    cols = f"{'slope x100':>10} {'t plain':>8} {'t NW':>8}"
    print(f"{'':<14} {cols}    {cols}")
    print(f"{'':<14} {'--- characteristic at t-1 ---':>28}    {'--- LEAK: characteristic at t ---':>28}")
    for k in ("log_bm", "log_cap"):
        a, b = fm_ok.loc[k], fm_leak.loc[k]
        print(f"{k:<14} {100 * a['mean']:>+10.3f} {a['t_plain']:>8.2f} {a['t_nw']:>8.2f}    "
              f"{100 * b['mean']:>+10.3f} {b['t_plain']:>8.2f} {b['t_nw']:>8.2f}")
    print(f"({fm_ok.attrs['n_periods']} cross-sections, Newey-West lags"
          f" {fm_ok.attrs['lags']} on the slope series)")

    # ---------------------------------------------------------------- 5. Ken French dates
    print("\n5. KEN FRENCH MONTHLY FILE DATES ARE 'YYYYMM': join on the month, not on a timestamp")
    stamps = [202601, 202602, 202603, 202604, 202605, 202606]
    fac = pd.DataFrame({"Mkt-RF": [1.5, -0.7, 2.1, 0.3, -1.2, 0.8]}, index=stamps)
    naive = fac.copy()
    naive.index = pd.to_datetime(pd.Index(stamps).astype(str), format="%Y%m")
    strat = pd.Series(np.arange(6) / 100.0, index=pd.date_range("2026-01-31", periods=6, freq="ME"))
    joined_naive = pd.concat([strat.rename("strategy"), naive], axis=1, join="inner")
    fac_p = fac.copy()
    fac_p.index = french_period_index(stamps, "monthly")
    joined = align_monthly(strat, fac_p)
    print(f"pd.to_datetime('202607', format='%Y%m') = {pd.to_datetime('202607', format='%Y%m').date()}"
          f" -> inner join with month-end strategy dates keeps {len(joined_naive)} of 6 rows;")
    print(f"french_period_index + align_monthly keeps {len(joined)} of 6. A daily file's YYYYMMDD stamp"
          f" joins on the day.")
    y5 = joined["strategy"].to_numpy()
    x5 = np.column_stack([np.ones(len(joined)), joined["Mkt-RF"].to_numpy()])
    b_pct = newey_west(y5, x5, 0)["beta"][1]
    x5d = np.column_stack([np.ones(len(joined)), joined["Mkt-RF"].to_numpy() / 100.0])
    b_dec = newey_west(y5, x5d, 0)["beta"][1]
    print(f"UNITS: regressing the same decimal strategy on the same column read as percent gives beta"
          f" {b_pct:.6f}, read as a decimal {b_dec:.4f} - a factor of {b_dec / b_pct:.0f}. Check the"
          f" scale of your own download; do not assume it.")

    print("\n" + "=" * 100)
    print("THE RULE:  characteristic at t, portfolio at t, return t->t+1 (lag >= 1); value-weight unless")
    print("           you mean to bet on microcaps; HAC standard errors with maxlags stated; and monthly")
    print("           factors with monthly returns, daily with daily, joined on the period.")
    print("=" * 100)
    print(f"total runtime {time.time() - t0:.1f}s")
